def take(source, names):
    ns = {}
    exec(source, ns)
    taken = {}
    for name in names:
        if name not in ns:
            raise ImportError("cannot import name " + repr(name))
        taken[name] = ns[name]
    return taken

def import_order(sources, requested):
    loaded = {}
    ran = []
    for name in requested:
        if name in loaded:
            continue
        ns = {"__name__": name}
        exec(sources[name], ns)
        loaded[name] = ns
        ran.append(name)
    return ran

def runs_when_imported(source):
    ns = {"__name__": "report"}
    exec(source, ns)
    return len(ns["log"]) > 0

def has_cycle(imports):
    for start in imports:
        pending = list(imports.get(start, []))
        seen = []
        while pending:
            name = pending.pop()
            if name == start:
                return True
            if name in seen:
                continue
            seen.append(name)
            for other in imports.get(name, []):
                pending.append(other)
    return False

