independent-practice.solution:
def module_card(source, name):
    ns = {"__name__": name}
    exec(source, ns)
    doc = ns.get("__doc__")
    if doc is None:
        doc = ""
    lines = doc.splitlines()
    summary = ""
    if lines:
        summary = lines[0]
    return {
        "name": ns["__name__"],
        "summary": summary,
        "public": sorted([n for n in ns if not n.startswith("_")]),
    }

