    ns = {}
    exec(source, ns)
    # __all__ decides, when the module bothered to state one
    pass

exam.solution:
def star_import(source):
    ns = {}
    exec(source, ns)
    if "__all__" in ns:
        return {name: ns[name] for name in ns["__all__"]}
    return {name: ns[name] for name in ns if not name.startswith("_")}

